python3 - <<'EOF'
import json,glob
for p in sorted(glob.glob('cases/*.record.json')):
    r=json.load(open(p))
    print('=====',p, list(r.keys()))
    l=r.get('lineup',{})
    print(' lineup:',{k:v for k,v in l.items() if k not in('remaining','culprit')}, (l.get('culprit') or {}).get('sha','')[:12], (l.get('culprit') or {}).get('probability'))
    m=r.get('motive') or {}
    print(' motive:',{k:(v if not isinstance(v,(list,str)) or len(str(v))<80 else str(v)[:80]+'...') for k,v in m.items() if k not in('steps',)})
    b=r.get('brief') or {}
    print(' brief model:',b.get('model'),'| headline:',b.get('headline'))
    for s in b.get('sentences',[]): print('   -',s['text'],s['cites'])
    print('   dropped:',b.get('dropped'))
    print(' ruling:',r.get('ruling'))
    f=r.get('fix') or {}
    print(' fix:',{k:v for k,v in f.items() if k not in('diff','failed_replays')})
    for a in r.get('attempts',[]): print('   attempt:',a['kind'],(a.get('commit') or '')[:12],a.get('verification'),a.get('note'))
    print(' damages:',r.get('damages'))
    for e in r.get('log',[]): print('   log:',e)
    print(' checks:',r.get('checks'))
    ev=r.get('evidence') or {}
    print(' evidence keys:',list(ev.keys()),'measured:',ev.get('measured'),'notes:',ev.get('notes'))
    print(' n replays:',len(r.get('replays',[])), 'n suspects', len(r.get('suspects',[])), 'alibis', sum(1 for s in r.get('suspects',[]) if s.get('alibi')))
EOF

